DROP INDEX only_one_owner;
CREATE TABLE account_access (
  user_id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK(role IN ('master','member')),
  disabled_at INTEGER
);
CREATE UNIQUE INDEX one_master ON account_access(role) WHERE role='master';
INSERT INTO account_access SELECT id,'master',NULL FROM user;
ALTER TABLE exercise ADD COLUMN user_id TEXT REFERENCES user(id);
ALTER TABLE program ADD COLUMN user_id TEXT REFERENCES user(id);
ALTER TABLE workout_template ADD COLUMN user_id TEXT REFERENCES user(id);
ALTER TABLE schedule_event ADD COLUMN user_id TEXT REFERENCES user(id);
ALTER TABLE weekly_assignment ADD COLUMN user_id TEXT REFERENCES user(id);
ALTER TABLE workout_session ADD COLUMN user_id TEXT REFERENCES user(id);
UPDATE exercise SET user_id=(SELECT id FROM user LIMIT 1);
UPDATE program SET user_id=(SELECT id FROM user LIMIT 1);
UPDATE workout_template SET user_id=(SELECT id FROM user LIMIT 1);
UPDATE schedule_event SET user_id=(SELECT id FROM user LIMIT 1);
UPDATE weekly_assignment SET user_id=(SELECT id FROM user LIMIT 1);
UPDATE workout_session SET user_id=(SELECT id FROM user LIMIT 1);
CREATE INDEX exercise_user ON exercise(user_id);
CREATE INDEX program_user ON program(user_id);
CREATE INDEX template_user ON workout_template(user_id);
CREATE INDEX schedule_user ON schedule_event(user_id,effective_at);
CREATE INDEX assignment_user ON weekly_assignment(user_id,week_id);
CREATE INDEX workout_user ON workout_session(user_id,started_at);
DROP INDEX one_unfinished_workout;
CREATE UNIQUE INDEX one_unfinished_workout ON workout_session(user_id) WHERE status IN ('active','paused');
ALTER TABLE settings RENAME TO legacy_settings;
CREATE TABLE settings (user_id TEXT PRIMARY KEY REFERENCES user(id), selected_program_id TEXT REFERENCES program(id));
INSERT INTO settings SELECT user.id,legacy_settings.selected_program_id FROM user CROSS JOIN legacy_settings;
DROP TABLE legacy_settings;
ALTER TABLE mutation_receipt RENAME TO legacy_receipt;
CREATE TABLE mutation_receipt (user_id TEXT NOT NULL REFERENCES user(id), id TEXT NOT NULL, fingerprint TEXT NOT NULL, result TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(user_id,id));
INSERT INTO mutation_receipt SELECT user.id,r.id,r.fingerprint,r.result,r.created_at FROM user CROSS JOIN legacy_receipt r;
DROP TABLE legacy_receipt;
CREATE TABLE account_audit (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES user(id), target_id TEXT NOT NULL REFERENCES user(id), action TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TRIGGER exercise_requires_owner BEFORE INSERT ON exercise WHEN NEW.user_id IS NULL BEGIN SELECT RAISE(ABORT,'Account owner required'); END;
CREATE TRIGGER exercise_owner_immutable BEFORE UPDATE OF user_id ON exercise WHEN OLD.user_id IS NOT NULL AND NEW.user_id IS NOT OLD.user_id BEGIN SELECT RAISE(ABORT,'Account owner cannot change'); END;
CREATE TRIGGER program_requires_owner BEFORE INSERT ON program WHEN NEW.user_id IS NULL BEGIN SELECT RAISE(ABORT,'Account owner required'); END;
CREATE TRIGGER program_owner_immutable BEFORE UPDATE OF user_id ON program WHEN OLD.user_id IS NOT NULL AND NEW.user_id IS NOT OLD.user_id BEGIN SELECT RAISE(ABORT,'Account owner cannot change'); END;
CREATE TRIGGER workout_template_requires_owner BEFORE INSERT ON workout_template WHEN NEW.user_id IS NULL BEGIN SELECT RAISE(ABORT,'Account owner required'); END;
CREATE TRIGGER workout_template_owner_immutable BEFORE UPDATE OF user_id ON workout_template WHEN OLD.user_id IS NOT NULL AND NEW.user_id IS NOT OLD.user_id BEGIN SELECT RAISE(ABORT,'Account owner cannot change'); END;
CREATE TRIGGER schedule_event_requires_owner BEFORE INSERT ON schedule_event WHEN NEW.user_id IS NULL BEGIN SELECT RAISE(ABORT,'Account owner required'); END;
CREATE TRIGGER schedule_event_owner_immutable BEFORE UPDATE OF user_id ON schedule_event WHEN OLD.user_id IS NOT NULL AND NEW.user_id IS NOT OLD.user_id BEGIN SELECT RAISE(ABORT,'Account owner cannot change'); END;
CREATE TRIGGER weekly_assignment_requires_owner BEFORE INSERT ON weekly_assignment WHEN NEW.user_id IS NULL BEGIN SELECT RAISE(ABORT,'Account owner required'); END;
CREATE TRIGGER weekly_assignment_owner_immutable BEFORE UPDATE OF user_id ON weekly_assignment WHEN OLD.user_id IS NOT NULL AND NEW.user_id IS NOT OLD.user_id BEGIN SELECT RAISE(ABORT,'Account owner cannot change'); END;
CREATE TRIGGER workout_session_requires_owner BEFORE INSERT ON workout_session WHEN NEW.user_id IS NULL BEGIN SELECT RAISE(ABORT,'Account owner required'); END;
CREATE TRIGGER workout_session_owner_immutable BEFORE UPDATE OF user_id ON workout_session WHEN OLD.user_id IS NOT NULL AND NEW.user_id IS NOT OLD.user_id BEGIN SELECT RAISE(ABORT,'Account owner cannot change'); END;
CREATE TRIGGER workout_template_scope_insert BEFORE INSERT ON workout_template WHEN NOT EXISTS(SELECT 1 FROM program p WHERE p.id=NEW.program_id AND p.user_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
CREATE TRIGGER workout_template_scope_update BEFORE UPDATE ON workout_template WHEN NOT EXISTS(SELECT 1 FROM program p WHERE p.id=NEW.program_id AND p.user_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
CREATE TRIGGER weekly_assignment_scope_insert BEFORE INSERT ON weekly_assignment WHEN NOT EXISTS(SELECT 1 FROM workout_template t WHERE t.id=NEW.template_id AND t.user_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
CREATE TRIGGER weekly_assignment_scope_update BEFORE UPDATE ON weekly_assignment WHEN NOT EXISTS(SELECT 1 FROM workout_template t WHERE t.id=NEW.template_id AND t.user_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
CREATE TRIGGER workout_session_scope_insert BEFORE INSERT ON workout_session WHEN NOT EXISTS(SELECT 1 FROM weekly_assignment a JOIN workout_template t ON t.id=NEW.template_id WHERE a.id=NEW.assignment_id AND a.user_id=NEW.user_id AND t.user_id=NEW.user_id AND a.template_id=NEW.template_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
CREATE TRIGGER workout_session_scope_update BEFORE UPDATE ON workout_session WHEN NOT EXISTS(SELECT 1 FROM weekly_assignment a JOIN workout_template t ON t.id=NEW.template_id WHERE a.id=NEW.assignment_id AND a.user_id=NEW.user_id AND t.user_id=NEW.user_id AND a.template_id=NEW.template_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
CREATE TRIGGER template_exercise_scope_insert BEFORE INSERT ON template_exercise WHEN NOT EXISTS(SELECT 1 FROM workout_template t JOIN exercise e ON e.id=NEW.exercise_id WHERE t.id=NEW.template_id AND t.user_id=e.user_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
CREATE TRIGGER template_exercise_scope_update BEFORE UPDATE ON template_exercise WHEN NOT EXISTS(SELECT 1 FROM workout_template t JOIN exercise e ON e.id=NEW.exercise_id WHERE t.id=NEW.template_id AND t.user_id=e.user_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
CREATE TRIGGER exercise_session_scope_insert BEFORE INSERT ON exercise_session WHEN NOT EXISTS(SELECT 1 FROM workout_session w JOIN exercise e ON e.id=NEW.exercise_id WHERE w.id=NEW.workout_id AND w.user_id=e.user_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
CREATE TRIGGER exercise_session_scope_update BEFORE UPDATE ON exercise_session WHEN NOT EXISTS(SELECT 1 FROM workout_session w JOIN exercise e ON e.id=NEW.exercise_id WHERE w.id=NEW.workout_id AND w.user_id=e.user_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
CREATE TRIGGER settings_scope_insert BEFORE INSERT ON settings WHEN NEW.selected_program_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM program p WHERE p.id=NEW.selected_program_id AND p.user_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
CREATE TRIGGER settings_scope_update BEFORE UPDATE ON settings WHEN NEW.selected_program_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM program p WHERE p.id=NEW.selected_program_id AND p.user_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'FOREIGN KEY account mismatch'); END;
